import React, { Component } from 'react'
import { LayoutWrapper } from './index.style'
import { Card, Table, Spin } from 'antd'
import { connect } from 'react-redux'
import policyActions from '../../../../redux/policy/actions'
import moment from 'moment-timezone'
// import teamActions from '../../../redux/team/actions'
// const { getAllUsers } = teamActions
const { bulkPolicyRetryEnqueueList, getbulkOperationList, resetReduxState } = policyActions
class BulkRetryList extends Component {
    state = {
      current: 1,
      tableSourceData: [],
      pagination: {},
      offset: 0,
      limit:0,
      isLoading:true,
    }
    componentWillReceiveProps (nextProps) {
      const {
        bulkOperationListData,
        bulkOperationListMessage
      } = nextProps
      if (bulkOperationListMessage === 'success') {
        this.setState({
          isLoading:false,
          tableSourceData: bulkOperationListData.data.details
        })
        this.props.resetReduxState(['bulkOperationListMessage'])
      }
    }
    detailPage (id, record) {
      const { push } = this.props.history
      const { id: fileId } = record
      push({
        pathname: `/policy/policy-retry-list/${fileId}`,
        state: {
          ...record
        }
      })
    }
    componentDidMount () {
      // this.props.getAllUsers()
      // this.props.bulkPolicyRetryEnqueueList()
      this.fetch()
    }
    

    fetch = (params = {}) => {
      const { offset, limit } = params
      const offsetNumber = Number(offset) || 0
      const limitNumber = Number(limit) || 10
      
      this.props.getbulkOperationList({
        limit: limitNumber,
        offset: offsetNumber,
      })
    }
    handleTableChange = pagination => {
      const { pageSize, current } = pagination
      const offset = pageSize * (current - 1)
      this.setState({
        pagination,
        offset,
        limit: pageSize
      }, () => {
        this.fetch({
          offset,
          limit: pageSize
        })
      })
    }
    render () {
      const { tableSourceData, offset, limit } = this.state
      const { policyretryListLoading } = this.props
      const tableColumns = [
        {
          title: 'Action',
          render: (val, record) => (
            <i
              className='far fa-eye'
              onClick={() => this.detailPage(val, record)}
              style={{
                cursor: 'pointer',
                textAlign: 'center'
              }}
            />
          )
        },
        {
          title: 'Filename',
          key: 'file_name',
          dataIndex: 'file_name'
        },
        {
          title: 'Status',
          key:'status',
          dataIndex:'status',
        },
        {
          title: 'Activity',
          key:'bulk_event_name',
          dataIndex:'bulk_event_name',
        },
        {
          title: 'Uploaded At',
          key: 'created_at',
          dataIndex: 'created_at',
          render: (value) => (moment(value).utc().format('DD/MM/YYYY hh:mm:ss'))
        },
        {
          title: 'Uploaded By',
          key: 'user',
          dataIndex: 'user'
        },
        {
          title: 'File URL',
          key: 'file_url',
          dataIndex: 'file_url'
        }
      ]
      return (
        <LayoutWrapper>
          <Card>
            <h1>Upload List</h1>
            <Spin spinning={this.state.isLoading}>
              <Table
                bordered
                columns={tableColumns}
                dataSource={tableSourceData}
                pagination={{
                  pageSize: 10,
                total: Number(tableSourceData.length),
                current: offset / limit + 1
                }}
                onChange={this.handleTableChange}
              />
            </Spin>
          </Card>
        </LayoutWrapper>
      )
    }
}

export default connect(
  state => ({
    policyretryListData: state.Policy.policyRetryList,
    policyretryListMessage: state.Policy.policyRetryListMessage,
    policyretryListLoading: state.Loading.BULK_POLICY_RETRY_LIST,
    policyretryListError: state.Error.BULK_POLICY_RETRY_LIST,
    bulkOperationListData: state.Policy.bulkOperationListData,
    bulkOperationListMessage: state.Policy.bulkOperationListMessage,
  }),
  {
    // getAllUsers,
    resetReduxState,
    bulkPolicyRetryEnqueueList,
    getbulkOperationList
  }
)(BulkRetryList)
